const navegador = await chromium.launch({ executablePath: process.env.CHROME ?? "/usr/bin/google-chrome", args: ["--no-sandbox"] });
async function abrir({ caido = false } = {}) {
  const ctx = await navegador.newContext({ viewport: { width: 1280, height: 900 }, acceptDownloads: true, locale: "es-ES", timezoneId: "Europe/Madrid" });
  await ctx.addInitScript(([k, v]) => localStorage.setItem(k, v), ["sb-sqartxsdlynecelkufyq-auth-token", JSON.stringify(sesion)]);
  const escrituras = [];
  await ctx.route("**/*.supabase.co/**", async (r) => {
    await new Promise((ok) => setTimeout(ok, LAT));
    if (caido) return r.abort("internetdisconnected");
    const req = r.request(); const u = new URL(req.url()); const tabla = u.pathname.match(/rest\/v1\/(?:rpc\/)?(\w+)/)?.[1];
    if (req.method() !== "GET") { escrituras.push({ tabla, url: req.url(), metodo: req.method(), cuerpo: (() => { try { return req.postDataJSON(); } catch { return null; } })() }); return r.fulfill({ status: 200, contentType: "application/json", body: tabla === "guardar_pedido" ? '"P-2026-0009"' : "[]" }); }
    if (!tabla) return r.fulfill({ status: 200, contentType: "application/json", body: "{}" });
    let filas = T[tabla] ?? [];
    for (const [k, v] of u.searchParams) if (v.startsWith("eq.") && ["id", "pedido_id", "favorito", "entregado"].includes(k)) filas = filas.filter((x) => String(x[k]) === v.slice(3));
    const uno = (req.headers()["accept"] ?? "").includes("vnd.pgrst.object");
    r.fulfill({ status: 200, contentType: "application/json", body: JSON.stringify(uno ? filas[0] ?? null : filas) });
  });
  const p = await ctx.newPage(); const errores = [];
  p.on("pageerror", (e) => errores.push(e.message));
  p.on("console", (m) => m.type() === "error" && !/WebSocket|realtime|ERR_INTERNET_DISCONNECTED|Failed to load resource/i.test(m.text()) && errores.push(m.text()));
  return { ctx, p, errores, escrituras };
}
const ir = async (p, ruta) => { await p.goto(BASE + ruta, { waitUntil: "networkidle" }); await p.waitForTimeout(500); };

const PAGS = [["inicio", "", "Nuevo pedido"], ["pedidos", "pedidos/", "P-2026-0002"], ["ficha", "pedidos/ver/?id=p1", "Prendas"], ["editor", "pedidos/nuevo/?id=p1", "Cliente y fecha"], ["clientes", "clientes/", "Marta"], ["catalogo", "catalogo/", "Beagle"], ["ajustes", "ajustes/", "Fotos de Roly"]];
const res = {};
async function red(p) { const c = await p.context().newCDPSession(p); await c.send("Network.emulateNetworkConditions", { offline: false, latency: Number(process.env.RTT || 70), downloadThroughput: Number(process.env.BW || 9e6) / 8, uploadThroughput: 1e6 / 8 }); await c.send("Emulation.setCPUThrottlingRate", { rate: 4 }); }
const ver = (p, t) => p.getByText(t, { exact: false }).first().waitFor({ timeout: 30000 });
// 1) apertura en frío (sin nada guardado)
for (const [n, ruta, t] of PAGS) {
  const { ctx, p } = await abrir(); await red(p);
  const t0 = Date.now(); await p.goto(BASE + ruta); await ver(p, t); res[n] = { frio: Date.now() - t0 };
  // 2) segunda apertura (código en caché del navegador, copia local de la sesión)
  const t1 = Date.now(); await p.goto(BASE + ruta); await ver(p, t); res[n].segunda = Date.now() - t1;
  await p.waitForTimeout(400);
  const t2 = Date.now(); await p.goto(BASE + ruta); await ver(p, t); res[n].tercera = Date.now() - t2;
  await ctx.close();
}
// 3) navegación dentro de la app (tocar el menú)
{
  const { ctx, p } = await abrir(); await red(p); await p.goto(BASE); await ver(p, "Nuevo pedido");
  for (const [n, , t, enlace] of [["pedidos", "", "P-2026-0002", "Pedidos"], ["clientes", "", "Marta", "Clientes"], ["catalogo", "", "Beagle", "Catálogo"], ["ajustes", "", "Fotos de Roly", "Ajustes"], ["pedidos2", "", "P-2026-0002", "Pedidos"]]) {
    const t0 = Date.now(); await p.getByRole("link", { name: enlace, exact: true }).first().click(); await ver(p, t); (res[n] ??= {}).navegar = Date.now() - t0;
    await p.waitForTimeout(300);
  }
  await ctx.close();
}
